fn swap_first_and_last(a: &Vec<i32>) -> Vec<i32> {
    let n = a.len();
    let mut result = Vec::with_capacity(n);
    
    if n == 1 {
        // If there's only one element, return it as is.
        result.push(a[0]);
    } else {
        // Swap the first and last elements
        result.push(a[n - 1]); // Last element of input becomes first in result
        for i in 1..n - 1 {
            result.push(a[i]); // Interior elements remain unchanged
        }
        result.push(a[0]); // First element of input becomes last in result
    }
    
    result
}